/**
 * Pinned self-hosted Graphviz/WASM renderer. It receives only presentation DOT
 * generated by this app, returns UTF-8 SVG text, and performs no network access.
 */
import { instance } from "@viz-js/viz";

interface RenderRequest {
  readonly type: "render";
  readonly id: string;
  readonly dot: string;
}

interface RenderSuccess {
  readonly type: "rendered";
  readonly id: string;
  readonly svg: string;
  readonly graphvizVersion: string;
  readonly warnings: readonly string[];
}

interface RenderFailure {
  readonly type: "failed";
  readonly id: string;
  readonly message: string;
}

interface WorkerScope {
  onmessage: ((event: MessageEvent<RenderRequest>) => void) | null;
  postMessage(message: RenderSuccess | RenderFailure): void;
}

const scope = globalThis as unknown as WorkerScope;
let renderer: Promise<Awaited<ReturnType<typeof instance>>> | null = null;
const MAX_DOT_BYTES = 200_000;

/** Lazily instantiate the bundled renderer once per worker. */
function loadRenderer(): Promise<Awaited<ReturnType<typeof instance>>> {
  renderer ??= instance();
  return renderer;
}

/** Render one bounded presentation DOT graph and post its SVG. */
async function render(request: RenderRequest): Promise<void> {
  try {
    if (new TextEncoder().encode(request.dot).byteLength > MAX_DOT_BYTES) {
      throw new Error("DOT exceeds the local render budget");
    }
    const viz = await loadRenderer();
    const result = viz.render(request.dot, { format: "svg", engine: "dot" });
    if (result.status !== "success") {
      throw new Error(result.errors.map((error) => error.message).join("; ") || "Graphviz render failure");
    }
    scope.postMessage({
      type: "rendered",
      id: request.id,
      svg: result.output,
      graphvizVersion: viz.graphvizVersion,
      warnings: result.errors.map((error) => error.message),
    });
  } catch (error) {
    scope.postMessage({
      type: "failed",
      id: request.id,
      message: error instanceof Error ? error.message : "Graphviz render failed",
    });
  }
}

scope.onmessage = (event) => {
  if (event.data?.type === "render" && typeof event.data.id === "string" && typeof event.data.dot === "string") {
    void render(event.data);
  }
};
